// Runtime for ApiFn-generated TypeScript clients. It has no dependencies and
// runs wherever `fetch`, `AbortController` and `URL` exist (Node 18+, browsers,
// edge runtimes). Generated by @apifn/sdk; regeneration overwrites this file.

/** Failure kinds shared with the apifn.client-failure/v1 event envelope. */
export type ApiFailureKind = "network" | "timeout" | "http" | "decode" | "validation" | "aborted" | "unknown";

/** A credential value, or a function that supplies one per request. */
export type CredentialSource<T = string> = T | (() => T | Promise<T>);

/** Username and password for an HTTP Basic scheme. */
export interface BasicCredential {
  username: string;
  password: string;
}

export interface RetryOptions {
  /** Total attempts, including the first (1 disables retries). Integer from 1 to 10. */
  maxAttempts?: number;
  /** Delay before the second attempt; doubles for each later one. */
  baseDelayMs?: number;
  /** Upper bound for any delay, including one asked for by `Retry-After`. */
  maxDelayMs?: number;
}

/**
 * Observation of a failed call, shaped as an apifn.client-failure/v1 event.
 * It never holds URLs, parameter values, bodies or credentials.
 */
export interface ClientFailureObservation {
  schemaVersion: "apifn.client-failure/v1";
  eventId: string;
  occurredAt: string;
  api: { id: string; version: string };
  operation: { id: string; name: string; method: string; pathTemplate: string };
  release: { releaseId: string; catalogDigest: string; sdk: { target: string; package: string; version: string } };
  failure: { kind: ApiFailureKind; httpStatus?: number; retryable: boolean; attempt: number };
}

export interface ClientOptions<Credentials> {
  /** Absolute http(s) URL every request is sent to; no user info, query or fragment. */
  baseUrl?: string;
  /** Transport; defaults to the global `fetch`. */
  fetch?: (input: string, init: RequestInit) => Promise<Response>;
  credentials?: Credentials;
  /** Per-attempt timeout, including reading the response body; it also bounds resolving credentials before the first attempt. */
  timeoutMs?: number;
  retry?: RetryOptions;
  /** Called once per failed call. Nothing is observed or sent unless this is set. */
  onFailure?: (event: ClientFailureObservation) => void;
}

export interface RequestOptions {
  signal?: AbortSignal;
  timeoutMs?: number;
  retry?: RetryOptions;
}

export class ApiError extends Error {
  readonly kind: ApiFailureKind;
  readonly operationId: string;
  /** Attempts made before this error, including the failed one. */
  readonly attempts: number;
  constructor(kind: ApiFailureKind, operationId: string, message: string, attempts: number, options?: { cause?: unknown }) {
    super(message, options);
    this.name = "ApiError";
    this.kind = kind;
    this.operationId = operationId;
    this.attempts = attempts;
  }
}

/**
 * A non-2xx response. `declared` is true when the operation documents the
 * status (exactly or as a range); `body` is decoded by the response media type.
 */
export class ApiHttpError<Status extends number = number, Body = unknown, Declared extends boolean = boolean> extends ApiError {
  readonly status: Status;
  readonly body: Body;
  readonly declared: Declared;
  readonly headers: Headers;
  constructor(operationId: string, message: string, attempts: number, status: Status, body: Body, declared: Declared, headers: Headers) {
    super("http", operationId, message, attempts);
    this.name = "ApiHttpError";
    this.status = status;
    this.body = body;
    this.declared = declared;
    this.headers = headers;
  }
}

export class ApiTimeoutError extends ApiError {
  constructor(operationId: string, message: string, attempts: number) {
    super("timeout", operationId, message, attempts);
    this.name = "ApiTimeoutError";
  }
}

export class ApiAbortError extends ApiError {
  constructor(operationId: string, message: string, attempts: number, cause: unknown) {
    super("aborted", operationId, message, attempts, { cause });
    this.name = "ApiAbortError";
  }
}

/** @internal How a response body was read: JSON, text, bytes, or no body. */
export type BodyKind = "json" | "text" | "binary" | "none";

/** @internal Operation metadata emitted by the generator. */
export interface ParameterSpec {
  key: string;
  name: string;
  in: "path" | "query" | "header";
  style: "simple" | "form" | "deepObject";
  explode: boolean;
  allowReserved: boolean;
  required: boolean;
}

/** @internal */
export type SecurityTerm =
  | { scheme: string; type: "bearer" }
  | { scheme: string; type: "basic" }
  | { scheme: string; type: "apiKey"; in: "header" | "query"; name: string };

/** @internal */
export interface OperationSpec {
  id: string;
  name: string;
  method: string;
  path: string;
  parameters: readonly ParameterSpec[];
  body: { mediaType: string; kind: "json" | "text" | "binary"; required: boolean } | null;
  accept: readonly string[];
  /** Body kinds a 2xx response may have; null when the operation documents no success response. */
  success: readonly BodyKind[] | null;
  /** Documented non-2xx statuses (exact codes, `4XX`-style ranges and `default`) and the body kinds each may have. */
  errors: readonly { status: string; kinds: readonly BodyKind[] }[];
  /** OR of ANDs; an empty alternative is anonymous. */
  security: readonly (readonly SecurityTerm[])[];
  /** "read": safe method; "idempotent": a write the catalog declares idempotent; "never": not retried. */
  retry: "read" | "idempotent" | "never";
}

/** @internal */
export interface SdkMetadata {
  apiId: string;
  apiVersion: string;
  catalogDigest: string;
  releaseId: string;
  target: string;
  packageName: string;
  packageVersion: string;
  defaultBaseUrl: string | null;
  defaultTimeoutMs: number;
  defaultRetry: Required<RetryOptions>;
}

const RETRY_STATUSES = new Set([408, 429, 500, 502, 503, 504]);
const MAX_ATTEMPTS = 10;
const MAX_TIMER_MS = 2_147_483_647;

function check(condition: boolean, message: string): void {
  if (!condition) throw new RangeError(message);
}

function checkDuration(value: number | undefined, name: string, min: number): void {
  if (value !== undefined) check(Number.isInteger(value) && value >= min && value <= MAX_TIMER_MS, `${name} must be an integer from ${min} to ${MAX_TIMER_MS}.`);
}

function resolveRetry(base: Required<RetryOptions>, override: RetryOptions | undefined): Required<RetryOptions> {
  if (override === undefined) return base;
  const maxAttempts = override.maxAttempts;
  if (maxAttempts !== undefined) check(Number.isInteger(maxAttempts) && maxAttempts >= 1 && maxAttempts <= MAX_ATTEMPTS, `retry.maxAttempts must be an integer from 1 to ${MAX_ATTEMPTS}.`);
  checkDuration(override.baseDelayMs, "retry.baseDelayMs", 0);
  checkDuration(override.maxDelayMs, "retry.maxDelayMs", 0);
  return {
    maxAttempts: maxAttempts ?? base.maxAttempts,
    baseDelayMs: override.baseDelayMs ?? base.baseDelayMs,
    maxDelayMs: override.maxDelayMs ?? base.maxDelayMs,
  };
}

/** Parses an absolute http(s) base URL; rejects user info, queries and fragments. */
function parseBaseUrl(value: string): URL {
  let url: URL;
  try {
    url = new URL(value);
  } catch {
    throw new RangeError("baseUrl must be an absolute http or https URL.");
  }
  check(url.protocol === "http:" || url.protocol === "https:", "baseUrl must use http or https.");
  check(url.username === "" && url.password === "", "baseUrl must not contain user info; pass credentials through the credentials option.");
  check(url.search === "" && url.hash === "" && !value.includes("?") && !value.includes("#"), "baseUrl must not contain a query or fragment.");
  return url;
}

// RFC 3986 unreserved characters stay as they are; everything else is percent-encoded.
function encode(value: string, allowReserved = false): string {
  const encoded = encodeURIComponent(value).replace(/[!'()*]/g, (c) => `%${c.charCodeAt(0).toString(16).toUpperCase()}`);
  if (!allowReserved) return encoded;
  // Reserved expansion: keep RFC 3986 reserved characters and existing percent-encoded triples, except
  // `#`, which would end the query.
  return encoded.replace(/%(3A|2F|3F|5B|5D|40|21|24|26|27|28|29|2A|2B|2C|3B|3D)/gi, (match) => decodeURIComponent(match)).replace(/%25([0-9A-Fa-f]{2})/g, "%$1");
}

type Primitive = string | number | boolean;

function isPrimitive(value: unknown): value is Primitive {
  return typeof value === "string" || (typeof value === "number" && Number.isFinite(value)) || typeof value === "boolean";
}

function isPlainObject(value: unknown): value is Record<string, unknown> {
  return typeof value === "object" && value !== null && !Array.isArray(value);
}

/** An own property only: names such as "constructor" or "toString" never read inherited values. */
function own(record: object, key: string): unknown {
  return Object.prototype.hasOwnProperty.call(record, key) ? (record as Record<string, unknown>)[key] : undefined;
}

class InputError extends Error {}

function primitive(value: unknown, where: string): string {
  if (!isPrimitive(value)) throw new InputError(`${where} must be a string, finite number or boolean.`);
  return String(value);
}

/** Flattens an object or array value into [name, value] pairs; nested containers are rejected. */
function members(value: unknown, where: string): Array<[string, string]> | string[] {
  if (Array.isArray(value)) return value.map((item, index) => primitive(item, `${where}[${index}]`));
  if (isPlainObject(value)) {
    return Object.keys(value)
      .filter((key) => value[key] !== undefined && value[key] !== null)
      .map((key) => [key, primitive(value[key], `${where}.${key}`)] as [string, string]);
  }
  return [primitive(value, where)];
}

function simple(value: unknown, explode: boolean, where: string, enc: (s: string) => string): string {
  const parts = members(value, where);
  if (parts.length === 0) return "";
  if (typeof parts[0] === "string") return (parts as string[]).map(enc).join(",");
  return (parts as Array<[string, string]>).map(([k, v]) => (explode ? `${enc(k)}=${enc(v)}` : `${enc(k)},${enc(v)}`)).join(",");
}

function queryPairs(spec: ParameterSpec, value: unknown, where: string): string[] {
  const enc = (s: string) => encode(s, spec.allowReserved);
  const name = encode(spec.name);
  if (spec.style === "deepObject") {
    if (!isPlainObject(value)) throw new InputError(`${where} must be an object for deepObject serialization.`);
    return (members(value, where) as Array<[string, string]>).map(([k, v]) => `${name}[${encode(k)}]=${enc(v)}`);
  }
  const parts = members(value, where);
  if (parts.length > 0 && typeof parts[0] !== "string") {
    const pairs = parts as Array<[string, string]>;
    return spec.explode ? pairs.map(([k, v]) => `${encode(k)}=${enc(v)}`) : [`${name}=${pairs.map(([k, v]) => `${enc(k)},${enc(v)}`).join(",")}`];
  }
  const values = parts as string[];
  if (Array.isArray(value) && values.length === 0) return [];
  return spec.explode ? values.map((v) => `${name}=${enc(v)}`) : [`${name}=${values.map(enc).join(",")}`];
}

/** The name of a query pair as a server decodes it (form encoding: "+" is a space). */
function pairName(pair: string): string {
  const raw = pair.split("=", 1)[0].replace(/\+/g, " ");
  try {
    return decodeURIComponent(raw);
  } catch {
    return raw;
  }
}

/** Whether an API key credential is sent under a parameter's name and location (header names ignore case). */
function supplies(term: SecurityTerm, spec: ParameterSpec): boolean {
  if (term.type !== "apiKey" || term.in !== spec.in) return false;
  return term.in === "header" ? term.name.toLowerCase() === spec.name.toLowerCase() : term.name === spec.name;
}

function headerValue(value: string, where: string): string {
  // Header values are Latin-1 text without control characters (tabs allowed), as fetch's Headers requires.
  if (/[^\t\x20-\x7e\x80-\xff]/.test(value)) throw new InputError(`${where} must not contain control characters or characters outside Latin-1.`);
  return value;
}

function setHeader(headers: Headers, name: string, value: string, where: string): void {
  try {
    headers.set(name, value);
  } catch (error) {
    throw new InputError(`${where} cannot be sent as header "${name}": ${error instanceof Error ? error.message : String(error)}`);
  }
}

async function resolveSource<T>(source: CredentialSource<T>): Promise<T> {
  return typeof source === "function" ? await (source as () => T | Promise<T>)() : source;
}

function base64(text: string): string {
  const bytes = new TextEncoder().encode(text);
  let binary = "";
  for (const byte of bytes) binary += String.fromCharCode(byte);
  return btoa(binary);
}

function mediaTypeOf(response: Response): string {
  return (response.headers.get("content-type") ?? "").split(";")[0].trim().toLowerCase();
}

function isJsonMediaType(type: string): boolean {
  return type === "application/json" || (type.startsWith("application/") && type.endsWith("+json"));
}

function isReplayable(body: BodyInit | null | undefined): boolean {
  return body === undefined || body === null || typeof body === "string" || body instanceof Uint8Array || body instanceof ArrayBuffer || (typeof Blob !== "undefined" && body instanceof Blob);
}

function randomId(): string {
  const bytes = new Uint8Array(12);
  const crypto = (globalThis as { crypto?: { getRandomValues?: (array: Uint8Array) => Uint8Array } }).crypto;
  if (crypto?.getRandomValues) crypto.getRandomValues(bytes);
  else for (let i = 0; i < bytes.length; i++) bytes[i] = Math.floor(Math.random() * 256);
  return `evt_${Array.from(bytes, (b) => b.toString(16).padStart(2, "0")).join("")}`;
}

/**
 * Settles with `promise`, or rejects with the signal's reason as soon as it aborts, so a consumer
 * callback (credential provider, transport, body stream) that ignores the signal cannot hold the call.
 */
function untilAborted<T>(promise: Promise<T>, signal: AbortSignal): Promise<T> {
  if (signal.aborted) {
    promise.catch(() => undefined);
    return Promise.reject(signal.reason);
  }
  return new Promise<T>((resolve, reject) => {
    const onAbort = () => reject(signal.reason);
    signal.addEventListener("abort", onAbort, { once: true });
    promise.then(
      (value) => {
        signal.removeEventListener("abort", onAbort);
        resolve(value);
      },
      (error: unknown) => {
        signal.removeEventListener("abort", onAbort);
        reject(error);
      }
    );
  });
}

/** Waits `ms`, or rejects with the signal's reason as soon as it aborts. */
function sleep(ms: number, signal: AbortSignal | undefined): Promise<void> {
  return new Promise((resolve, reject) => {
    if (signal?.aborted) return reject(signal.reason);
    const onAbort = () => {
      clearTimeout(timer);
      reject(signal?.reason);
    };
    const timer = setTimeout(() => {
      signal?.removeEventListener("abort", onAbort);
      resolve();
    }, ms);
    signal?.addEventListener("abort", onAbort, { once: true });
  });
}

/** Seconds or an HTTP date, as `Retry-After` allows; null when absent or unreadable. */
function retryAfterMs(response: Response): number | null {
  const value = response.headers.get("retry-after");
  if (value === null) return null;
  if (/^\d+$/.test(value.trim())) return Number(value.trim()) * 1000;
  const date = Date.parse(value);
  return Number.isNaN(date) ? null : Math.max(0, date - Date.now());
}

const TIMEOUT = Symbol("timeout");

/** @internal Executes generated operations. */
export class ApiRuntime<Credentials> {
  readonly #meta: SdkMetadata;
  readonly #base: URL;
  readonly #fetch: (input: string, init: RequestInit) => Promise<Response>;
  readonly #credentials: Record<string, CredentialSource<string | BasicCredential> | undefined>;
  readonly #timeoutMs: number;
  readonly #retry: Required<RetryOptions>;
  readonly #onFailure: ClientOptions<Credentials>["onFailure"];

  constructor(meta: SdkMetadata, options: ClientOptions<Credentials>) {
    this.#meta = meta;
    const baseUrl = options.baseUrl ?? meta.defaultBaseUrl;
    if (baseUrl === null) throw new RangeError("baseUrl is required: this SDK was generated without a default base URL.");
    this.#base = parseBaseUrl(baseUrl);
    if (options.fetch === undefined && typeof globalThis.fetch !== "function") throw new RangeError("No fetch implementation: pass the fetch option.");
    this.#fetch = options.fetch ?? ((input, init) => globalThis.fetch(input, init));
    this.#credentials = (options.credentials ?? {}) as Record<string, CredentialSource<string | BasicCredential> | undefined>;
    checkDuration(options.timeoutMs, "timeoutMs", 1);
    this.#timeoutMs = options.timeoutMs ?? meta.defaultTimeoutMs;
    this.#retry = resolveRetry(meta.defaultRetry, options.retry);
    this.#onFailure = options.onFailure;
  }

  async request(op: OperationSpec, params: Record<string, unknown> | undefined, options: RequestOptions = {}): Promise<unknown> {
    const values = params ?? {};
    let attempts = 0;
    let retryable = false;
    try {
      checkDuration(options.timeoutMs, "timeoutMs", 1);
      const retry = resolveRetry(this.#retry, options.retry);
      const timeoutMs = options.timeoutMs ?? this.#timeoutMs;
      const prepared = await this.#guard(op, timeoutMs, options.signal, attempts, (signal) => this.#prepare(op, values, signal));
      // Only reads and declared-idempotent writes are retried, and never with a body that cannot be sent twice (a stream).
      const eligible = op.retry !== "never" && isReplayable(prepared.init.body);
      const budget = eligible ? retry.maxAttempts : 1;
      for (;;) {
        attempts += 1;
        retryable = false;
        const outcome = await this.#attempt(op, prepared, timeoutMs, options.signal, attempts);
        if (outcome.ok) return outcome.value;
        retryable = eligible && outcome.retryable;
        if (!retryable || attempts >= budget) throw outcome.error;
        const backoff = Math.min(retry.maxDelayMs, retry.baseDelayMs * 2 ** (attempts - 1));
        await sleep(Math.min(retry.maxDelayMs, outcome.retryAfterMs ?? backoff), options.signal).catch((reason) => {
          retryable = false;
          throw new ApiAbortError(op.id, `${op.method} ${op.path} was aborted.`, attempts, reason);
        });
      }
    } catch (error) {
      const failure =
        error instanceof ApiError
          ? error
          : error instanceof InputError || error instanceof RangeError
            ? new ApiError("validation", op.id, error.message, attempts, { cause: error })
            : new ApiError("unknown", op.id, `${op.method} ${op.path} failed.`, attempts, { cause: error });
      this.#observe(op, failure, retryable);
      throw failure;
    }
  }

  /**
   * Runs `task` under the caller signal and a `timeoutMs` timer: it rejects with ApiAbortError or
   * ApiTimeoutError as soon as either fires, whether or not `task` observes the signal it is given.
   */
  async #guard<T>(op: OperationSpec, timeoutMs: number, signal: AbortSignal | undefined, attempt: number, task: (signal: AbortSignal) => Promise<T>): Promise<T> {
    const label = `${op.method} ${op.path}`;
    if (signal?.aborted) throw new ApiAbortError(op.id, `${label} was aborted.`, attempt, signal.reason);
    const controller = new AbortController();
    const onAbort = () => controller.abort(signal?.reason);
    signal?.addEventListener("abort", onAbort, { once: true });
    const timer = setTimeout(() => controller.abort(TIMEOUT), timeoutMs);
    try {
      return await untilAborted(task(controller.signal), controller.signal);
    } catch (error) {
      if (controller.signal.aborted) {
        if (controller.signal.reason === TIMEOUT) throw new ApiTimeoutError(op.id, `${label} timed out after ${timeoutMs} ms.`, attempt);
        throw new ApiAbortError(op.id, `${label} was aborted.`, attempt, signal?.reason);
      }
      throw error;
    } finally {
      clearTimeout(timer);
      signal?.removeEventListener("abort", onAbort);
    }
  }

  async #prepare(op: OperationSpec, values: Record<string, unknown>, signal: AbortSignal): Promise<{ url: string; init: RequestInit }> {
    const headers = new Headers();
    const query: string[] = [];
    let path = op.path;
    // A required parameter an API key credential can supply is checked once the credential is chosen.
    const pending: ParameterSpec[] = [];
    for (const spec of op.parameters) {
      const value = own(values, spec.key);
      const where = `Parameter ${spec.key}`;
      if (value === undefined || value === null) {
        if (spec.required && op.security.some((terms) => terms.some((term) => supplies(term, spec)))) pending.push(spec);
        else if (spec.required) throw new InputError(`${where} is required.`);
        continue;
      }
      if (spec.in === "path") {
        const segment = simple(value, spec.explode, where, (s) => encode(s));
        // Dot segments would be removed by URL normalization and move the request to another path.
        if (segment === "" || segment === "." || segment === "..") throw new InputError(`${where} must be a non-empty path segment other than "." or "..".`);
        path = path.split(`{${spec.name}}`).join(segment);
      } else if (spec.in === "query") {
        query.push(...queryPairs(spec, value, where));
      } else {
        setHeader(headers, spec.name, headerValue(simple(value, spec.explode, where, (s) => s), where), where);
      }
    }
    let body: BodyInit | undefined;
    if (op.body) {
      const input = own(values, "body");
      if (input === undefined) {
        if (op.body.required) throw new InputError("Parameter body is required.");
      } else if (op.body.kind === "json") {
        body = JSON.stringify(input);
        if (body === undefined) throw new InputError("Parameter body must be JSON-serializable.");
      } else if (op.body.kind === "text") {
        if (typeof input !== "string") throw new InputError("Parameter body must be a string.");
        body = input;
      } else {
        const binary = input instanceof Uint8Array || input instanceof ArrayBuffer || (typeof Blob !== "undefined" && input instanceof Blob) || (typeof ReadableStream !== "undefined" && input instanceof ReadableStream);
        if (!binary) throw new InputError("Parameter body must be a Uint8Array, ArrayBuffer, Blob or ReadableStream.");
        body = input as BodyInit;
      }
      if (body !== undefined) headers.set("content-type", op.body.mediaType);
    }
    if (op.accept.length > 0) headers.set("accept", op.accept.join(", "));
    const applied = await this.#authorize(op, headers, query, signal);
    for (const spec of pending) {
      if (!applied.some((term) => supplies(term, spec))) throw new InputError(`Parameter ${spec.key} is required.`);
    }

    const base = this.#base.href.replace(/\/+$/, "");
    const url = `${base}${path}${query.length > 0 ? `?${query.join("&")}` : ""}`;
    // Host-bound: the request URL keeps the configured origin and path prefix whatever the parameter values.
    const parsed = new URL(url);
    const prefix = this.#base.pathname.replace(/\/+$/, "");
    if (parsed.origin !== this.#base.origin || (prefix !== "" && parsed.pathname !== prefix && !parsed.pathname.startsWith(`${prefix}/`))) {
      throw new InputError("Parameters must not move the request outside the configured base URL.");
    }
    const init: RequestInit & { duplex?: "half" } = { method: op.method, headers, body, redirect: "manual" };
    if (typeof ReadableStream !== "undefined" && body instanceof ReadableStream) init.duplex = "half";
    // A request fetch refuses to build (a forbidden method, a body on GET or HEAD) fails here as invalid
    // input, never later as a retryable network error. The body is checked without consuming a stream.
    if ((op.method === "GET" || op.method === "HEAD") && body !== undefined) throw new InputError(`A ${op.method} request cannot have a body.`);
    if (typeof Request === "function") {
      try {
        new Request(url, { method: op.method, headers });
      } catch (error) {
        throw new InputError(`${op.method} ${op.path} cannot be sent with fetch: ${error instanceof Error ? error.message : String(error)}`);
      }
    }
    return { url, init };
  }

  /**
   * Applies the first credentialed security alternative whose credentials are all configured; an
   * anonymous alternative is used only when none is, so optional authentication still sends credentials.
   * A credential replaces any parameter sent under the same header or query name. Returns the terms applied.
   */
  async #authorize(op: OperationSpec, headers: Headers, query: string[], signal: AbortSignal): Promise<readonly SecurityTerm[]> {
    const satisfied = op.security.filter((terms) => terms.every((term) => own(this.#credentials, term.scheme) !== undefined));
    const alternative = satisfied.find((terms) => terms.length > 0);
    if (!alternative) return [];
    for (const term of alternative) {
      const source = own(this.#credentials, term.scheme) as CredentialSource<string | BasicCredential>;
      const value = await untilAborted(resolveSource(source), signal);
      const where = `Credential ${term.scheme}`;
      if (term.type === "basic") {
        const pair = value as BasicCredential;
        if (!isPlainObject(pair) || typeof pair.username !== "string" || typeof pair.password !== "string" || pair.username.includes(":")) {
          throw new InputError(`${where} must be { username, password } with no ":" in the username.`);
        }
        headers.set("authorization", headerValue(`Basic ${base64(`${pair.username}:${pair.password}`)}`, where));
        continue;
      }
      if (typeof value !== "string" || value === "") throw new InputError(`${where} must be a non-empty string.`);
      if (term.type === "bearer") headers.set("authorization", headerValue(`Bearer ${value}`, where));
      else if (term.in === "header") setHeader(headers, term.name, headerValue(value, where), where);
      else {
        // Like a header credential, a query credential is the only value sent under its name. Entries are
        // split into wire pairs first, since reserved expansion can put "&" and "=" in a value, and every
        // pair whose decoded name is the credential name or a deepObject member of it ("name[...]") is dropped.
        const kept = query.flatMap((entry) => entry.split("&")).filter((pair) => {
          const name = pairName(pair);
          return name !== term.name && !name.startsWith(`${term.name}[`);
        });
        query.splice(0, query.length, ...kept, `${encode(term.name)}=${encode(value)}`);
      }
    }
    return alternative;
  }

  async #attempt(
    op: OperationSpec,
    prepared: { url: string; init: RequestInit },
    timeoutMs: number,
    signal: AbortSignal | undefined,
    attempt: number
  ): Promise<{ ok: true; value: unknown } | { ok: false; error: ApiError; retryable: boolean; retryAfterMs: number | null }> {
    const label = `${op.method} ${op.path}`;
    if (signal?.aborted) throw new ApiAbortError(op.id, `${label} was aborted.`, attempt, signal.reason);
    const controller = new AbortController();
    const onAbort = () => controller.abort(signal?.reason);
    signal?.addEventListener("abort", onAbort, { once: true });
    const timer = setTimeout(() => controller.abort(TIMEOUT), timeoutMs);
    const settle = (error: unknown): never => {
      if (controller.signal.reason === TIMEOUT) throw new ApiTimeoutError(op.id, `${label} timed out after ${timeoutMs} ms.`, attempt);
      if (signal?.aborted) throw new ApiAbortError(op.id, `${label} was aborted.`, attempt, signal.reason);
      throw error;
    };
    try {
      let response: Response;
      try {
        const sent = Promise.resolve().then(() => this.#fetch(prepared.url, { ...prepared.init, signal: controller.signal }));
        // A response that arrives after the attempt was given up is never read: cancel its body.
        sent.then(
          (late) => {
            if (controller.signal.aborted) discard(late);
          },
          () => undefined
        );
        response = await untilAborted(sent, controller.signal);
      } catch (error) {
        settle(new ApiError("network", op.id, `${label} failed before a response was received.`, attempt, { cause: error }));
        throw error;
      }
      const status = response.status;
      let body = NO_CONTENT;
      try {
        body = await untilAborted(decode(response, op.method, controller.signal), controller.signal);
      } catch (error) {
        settle(new ApiError("network", op.id, `${label} failed while reading the response body.`, attempt, { cause: error }));
      }
      if (status >= 200 && status < 300) {
        // A success body must be one the operation documents, so the result matches its type.
        if (op.success !== null) body = asDocumented(body, op.success);
        if (body.kind === "invalid-json" || (op.success !== null && !op.success.includes(body.kind))) {
          throw new ApiError("decode", op.id, `${label} returned a ${body.kind === "invalid-json" ? "malformed JSON" : body.kind} body, which the operation does not document.`, attempt);
        }
        return { ok: true, value: body.value };
      }
      // Declared: a documented status (an exact code, else a range, else default) with a body of a documented kind.
      // An opaque redirect (browser fetch with redirect: "manual") reports status 0 and is never declared.
      const code = String(status);
      const entry =
        op.errors.find((candidate) => candidate.status === code) ??
        op.errors.find((candidate) => candidate.status === `${code[0]}XX`) ??
        op.errors.find((candidate) => candidate.status === "default");
      if (entry !== undefined) body = asDocumented(body, entry.kinds);
      const kind: BodyKind = body.kind === "invalid-json" ? "text" : body.kind;
      const declared = status !== 0 && entry !== undefined && entry.kinds.includes(kind);
      const error = new ApiHttpError(op.id, `${label} returned HTTP ${status}.`, attempt, status, body.value, declared, response.headers);
      return { ok: false, error, retryable: RETRY_STATUSES.has(status), retryAfterMs: retryAfterMs(response) };
    } catch (error) {
      if (error instanceof ApiTimeoutError || (error instanceof ApiError && error.kind === "network")) {
        return { ok: false, error, retryable: true, retryAfterMs: null };
      }
      throw error;
    } finally {
      clearTimeout(timer);
      signal?.removeEventListener("abort", onAbort);
    }
  }

  #observe(op: OperationSpec, error: ApiError, retryable: boolean): void {
    const hook = this.#onFailure;
    if (!hook) return;
    const meta = this.#meta;
    const event: ClientFailureObservation = {
      schemaVersion: "apifn.client-failure/v1",
      eventId: randomId(),
      occurredAt: new Date().toISOString(),
      api: { id: meta.apiId, version: meta.apiVersion },
      operation: { id: op.id, name: op.name, method: op.method.toLowerCase(), pathTemplate: op.path },
      release: { releaseId: meta.releaseId, catalogDigest: meta.catalogDigest, sdk: { target: meta.target, package: meta.packageName, version: meta.packageVersion } },
      failure: { kind: error.kind, retryable, attempt: Math.max(1, error.attempts) },
    };
    if (error instanceof ApiHttpError && error.status >= 100) event.failure.httpStatus = error.status;
    // An observer never changes the call's outcome. Any thenable it returns, from any realm, is adopted
    // and its rejection handled; a throwing `then` getter rejects the adopting promise, handled the same way.
    try {
      const result = hook(event) as unknown;
      if ((typeof result === "object" && result !== null) || typeof result === "function") {
        Promise.resolve(result).then(undefined, () => undefined);
      }
    } catch {
      // ignored
    }
  }
}

/** `empty` marks the empty value of a text or binary media type, which may instead be documented as no content. */
type Decoded = { kind: BodyKind; value: unknown; empty?: true } | { kind: "invalid-json"; value: string };

const NO_CONTENT: Decoded = { kind: "none", value: undefined };

/** Reads an empty text or binary body as no content when the documented kinds include it. */
function asDocumented(body: Decoded, kinds: readonly BodyKind[]): Decoded {
  return "empty" in body && kinds.includes("none") ? NO_CONTENT : body;
}

/** Statuses whose responses never have content. */
const BODYLESS_STATUSES = new Set([204, 205, 304]);

/**
 * Reads the whole body inside the attempt's timeout and classifies it by media type. An empty body is
 * no content for HEAD, 204, 205, 304, a missing media type and JSON (an empty JSON body is not a JSON
 * document); for a text or binary media type it is an empty string or byte array marked `empty`, which
 * `asDocumented` turns into no content when the status documents none (frameworks often send a media
 * type with an empty body).
 */
async function decode(response: Response, method: string, signal: AbortSignal): Promise<Decoded> {
  if (response.type === "opaqueredirect") return NO_CONTENT;
  const bytes = response.body === null ? new Uint8Array(0) : await readBody(response.body, signal);
  const type = mediaTypeOf(response);
  if (bytes.byteLength === 0) {
    if (method === "HEAD" || BODYLESS_STATUSES.has(response.status) || type === "" || isJsonMediaType(type)) return NO_CONTENT;
    return type.startsWith("text/") ? { kind: "text", value: "", empty: true } : { kind: "binary", value: bytes, empty: true };
  }
  if (isJsonMediaType(type)) {
    const text = new TextDecoder().decode(bytes);
    try {
      return { kind: "json", value: JSON.parse(text) as unknown };
    } catch {
      return { kind: "invalid-json", value: text };
    }
  }
  if (type.startsWith("text/")) return { kind: "text", value: new TextDecoder().decode(bytes) };
  return { kind: "binary", value: bytes };
}

/** Reads a body to the end; when `signal` aborts it cancels the body, so a stream that ignores the signal stops being read. */
async function readBody(body: ReadableStream<Uint8Array>, signal: AbortSignal): Promise<Uint8Array> {
  const reader = body.getReader();
  const cancel = () => {
    reader.cancel(signal.reason).catch(() => undefined);
  };
  if (signal.aborted) cancel();
  else signal.addEventListener("abort", cancel, { once: true });
  try {
    const chunks: Uint8Array[] = [];
    let size = 0;
    for (;;) {
      const { done, value } = await reader.read();
      if (signal.aborted) throw signal.reason;
      if (done) break;
      chunks.push(value);
      size += value.byteLength;
    }
    const bytes = new Uint8Array(size);
    let offset = 0;
    for (const chunk of chunks) {
      bytes.set(chunk, offset);
      offset += chunk.byteLength;
    }
    return bytes;
  } finally {
    signal.removeEventListener("abort", cancel);
  }
}

/** Cancels the body of a response that will not be read. */
function discard(response: Response | undefined): void {
  try {
    const body = response?.body;
    if (body && !body.locked) body.cancel().catch(() => undefined);
  } catch {
    // ignored
  }
}
